package dao;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.sql.Statement;
import org.junit.jupiter.api.BeforeEach;

abstract class DaoTest {
    private static final String URL = "jdbc:h2:mem:coursess_m1;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1";

    @BeforeEach
    void setUp() throws SQLException {
        try (Connection con = DriverManager.getConnection(URL, "sa", ""); Statement st = con.createStatement()) {
            st.execute("DROP ALL OBJECTS");
            st.execute("CREATE TABLE users (id BIGINT PRIMARY KEY, full_name VARCHAR(120), username VARCHAR(120), role VARCHAR(20), is_active BOOLEAN)");
            st.execute("CREATE TABLE categories (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(120), description VARCHAR(255))");
            st.execute("CREATE TABLE courses (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title VARCHAR(200) NOT NULL, description VARCHAR(255), thumbnail_url VARCHAR(2048), status VARCHAR(20) NOT NULL, teacher_id BIGINT NOT NULL, category_id BIGINT NOT NULL)");
            st.execute("CREATE TABLE lessons (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title VARCHAR(200), video_url VARCHAR(2048), order_index INT, is_visible BOOLEAN, course_id BIGINT)");
            st.execute("CREATE TABLE lesson_documents (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(255), file_path VARCHAR(512), file_size BIGINT, is_available BOOLEAN, lesson_id BIGINT)");
            st.execute("CREATE TABLE course_members (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, student_id BIGINT, course_id BIGINT, enrolled_at TIMESTAMP(6), UNIQUE(student_id, course_id))");
            st.execute("CREATE TABLE quizzes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title VARCHAR(200), status VARCHAR(20), published_at TIMESTAMP(6), lesson_id BIGINT, created_by BIGINT, source_quiz_id BIGINT)");
            st.execute("CREATE TABLE questions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, content TEXT, order_index INT, quiz_id BIGINT)");
            st.execute("CREATE TABLE question_options (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, content TEXT, is_correct BOOLEAN, order_index INT, question_id BIGINT)");
            st.execute("CREATE TABLE quiz_attempts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, status VARCHAR(20), total_questions INT, correct_count INT, score DECIMAL(5, 2), started_at TIMESTAMP(6), submitted_at TIMESTAMP(6), student_id BIGINT, quiz_id BIGINT)");
            st.execute("CREATE TABLE student_answers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, is_correct BOOLEAN, attempt_id BIGINT, question_id BIGINT, selected_option_id BIGINT)");


            st.execute("INSERT INTO users VALUES (1,'Giáo viên','teacher','TEACHER',TRUE),(2,'Học sinh','student','STUDENT',TRUE),(3,'Học sinh khóa','blocked','STUDENT',FALSE),(4,'Quản trị viên','admin','ADMIN',TRUE)");
            st.execute("INSERT INTO categories VALUES (1,'Lập trình','Các khóa học lập trình'),(2,'Ngoại ngữ','Các khóa học ngoại ngữ')");
            st.execute("INSERT INTO courses VALUES (10,'Java cơ bản','Nhập môn Java',NULL,'OPEN',1,1),(11,'Java nâng cao','Java chuyên sâu',NULL,'CLOSED',1,1),(12,'Tiếng Anh','Giao tiếp',NULL,'DRAFT',1,2),(13,'SQL cơ bản','Cơ sở dữ liệu',NULL,'OPEN',1,1)");
            st.execute("INSERT INTO lessons VALUES (20,'Bài hai','https://youtube.com/2',2,TRUE,10),(21,'Bài ẩn','https://youtube.com/3',3,FALSE,10),(22,'Bài một','https://youtube.com/1',1,TRUE,10)");
        }
    }

}
